def ring_grid(h,w,bg,rings):
    g=[[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in rings:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1): g[r][c]=color
    return g
def expected_fill(h,w,bg,rings):
    g=ring_grid(h,w,bg,rings)
